]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{primary} 194}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} WHO Member States\\Coordinated}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.33\linewidth}\centering
    \fcolorbox{accent!60}{accent!12!white}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{accent!85!black} \raisebox{2pt}{\fontsize{28}{34}\selectfont$\sim$}1.9B}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} COVAX Vaccine Doses\\Delivered by Mid-2023}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{46}{56}\selectfont\bfseries\color{primary} 200+}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Technical Guidance\\Documents Issued}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% INTRO / CONTEXT — Left column, rows 5-8
% ══════════════════════════════════════════════════
\posterbox[whocard, title={The Global Response Framework}
]{name=intro, column=1, between=row5 and row8}{
  \fontsize{20}{28}\selectfont
  WHO coordinates a structured, multi-phase process across all \textbf{6 WHO regions}---Africa, the Americas, South-East Asia, Europe, the Eastern Mediterranean, and the Western Pacific.\\[4pt]
  \colorbox{primary!18}{\parbox{0.94\linewidth}{\centering\vspace{3pt}%
    {\fontsize{18}{24}\selectfont\color{primary} First Disease Outbreak News issued \textbf{5 January 2020}---days after initial reports from Wuhan, China.}%
  \vspace{3pt}}}\\[4pt]
  {\fontsize{18}{24}\selectfont\color{textgray} This poster visualizes the five-phase flow from initial surveillance through long-term recovery.}
}

% ══════════════════════════════════════════════════
% KEY METRICS — Right column, rows 5-8
% ══════════════════════════════════════════════════
\posterbox[ambercard, title={Coordination at Scale}
]{name=metrics, column=2, between=row5 and row8}{
  \fontsize{20}{28}\selectfont
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{primary!18}{\parbox{0.92\linewidth}{\vspace{3pt}\centering
      {\fontsize{30}{36}\selectfont\bfseries\color{primary} 6}\\[-1pt]
      {\fontsize{16}{20}\selectfont WHO Regions Covered}
    \vspace{3pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{accent!18}{\parbox{0.92\linewidth}{\vspace{3pt}\centering
      {\fontsize{30}{36}\selectfont\bfseries\color{accent!85!black} 146}\\[-1pt]
      {\fontsize{16}{20}\selectfont Countries Received\\COVAX Doses}
    \vspace{3pt}}}
  \end{minipage}\\[8pt]
  \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{3pt}\centering
    {\fontsize{16}{22}\selectfont\color{textdark} COVID-19 dashboard tracked \textbf{millions of data points daily},\\ providing real-time situational awareness to decision-makers worldwide.}
  \vspace{3pt}}}
}

% ══════════════════════════════════════════════════
% PHASE 1 — Left column, rows 8-11
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase1, column=1, between=row8 and row11}{
  {\phasenum{1}\hspace{6pt}{\fontsize{24}{30}\selectfont\bfseries\color{primary} Surveillance \& Early Detection}}\\[6pt]
  \fontsize{20}{28}\selectfont
  \begin{itemize}
    \item National labs report unusual respiratory clusters to WHO via \textbf{IHR framework}
    \item Disease Outbreak News bulletins and Weekly Epidemiological Records keep the global community informed
    \item Rapid identification of novel pathogens through established surveillance channels
  \end{itemize}
}

% ══════════════════════════════════════════════════
% PHASE 2 — Right column, rows 8-11
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase2, column=2, between=row8 and row11}{
  {\phasenum{2}\hspace{6pt}{\fontsize{24}{30}\selectfont\bfseries\color{primary} Risk Assessment \& Alert}}\\[6pt]
  \fontsize{20}{28}\selectfont
  \begin{itemize}
    \item WHO evaluates \textbf{likelihood of spread}, severity of illness, and health system capacity
    \item Situation reports issued regularly to all Member States
    \item Independent Oversight Committee reviews alert adequacy
  \end{itemize}
  \vspace{4pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{\vspace{3pt}\centering
    {\fontsize{18}{24}\selectfont\color{accent!80!black}\textbf{PHEIC declared 30 January 2020}}
  \vspace{3pt}}}
}

% ══════════════════════════════════════════════════
% PHASE 3 — spans both columns, rows 11-14
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase3, column=1, span=2, between=row11 and row14}{
  {\phasenum{3}\hspace{6pt}{\fontsize{24}{30}\selectfont\bfseries\color{primary} Response Operations \& Clinical Management}}\\[6pt]
  \fontsize{20}{28}\selectfont
  WHO mobilizes technical teams through the \textbf{Health Emergencies Programme}, with partners including UNICEF, World Bank, and M\'{e}decins Sans Fronti\`{e}res.\\[6pt]
  \begin{minipage}[t]{0.48\linewidth}
    \renewcommand{\arraystretch}{1.35}
    \fontsize{18}{24}\selectfont
    \begin{tabular}{p{0.35\linewidth}p{0.58\linewidth}}
      \rowcolor{primary!15} \textbf{\color{primary}Response Pillar} & \textbf{\color{primary}Key Activities} \\
      Infection Prevention & PPE guidance, hand hygiene, facility decontamination \\
      \rowcolor{primary!6} Clinical Management & Treatment protocols, oxygen therapy, ICU guidelines \\
      Health Workforce & Training, surge staffing, mental health support \\
    \end{tabular}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \renewcommand{\arraystretch}{1.35}
    \fontsize{18}{24}\selectfont
    \begin{tabular}{p{0.35\linewidth}p{0.58\linewidth}}
      \rowcolor{primary!15} \textbf{\color{primary}Response Pillar} & \textbf{\color{primary}Key Activities} \\
      Supply Chain & Essential medicines, diagnostics, equipment procurement \\
      \rowcolor{primary!6} Research & Solidarity Trial, vaccine R\&D coordination \\
    \end{tabular}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% CONNECTOR ARROW between Phase 3 and Phase 4
% ══════════════════════════════════════════════════

% ══════════════════════════════════════════════════
% PHASE 4 — spans both columns, rows 14-18 (highlighted, largest section)
% ══════════════════════════════════════════════════
\posterbox[phase4card
]{name=phase4, column=1, span=2, between=row14 and row18}{
  {\phasenumhighlight{4}\hspace{6pt}{\fontsize{26}{32}\selectfont\bfseries\color{accent!85!black} Public Health \& Social Measures}}\\[6pt]
  \fontsize{20}{28}\selectfont
  Community-level interventions are critical to slowing transmission and protecting populations.\\[6pt]
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{accent!15}{\parbox{0.92\linewidth}{\vspace{4pt}
      {\fontsize{20}{26}\selectfont\bfseries\color{accent!85!black} Testing \& Contact Tracing}\\[2pt]
      {\fontsize{18}{24}\selectfont Scaled PCR and rapid antigen testing; digital and manual contact tracing systems deployed globally.}
    \vspace{4pt}}}\\[6pt]
    \colorbox{accent!15}{\parbox{0.92\linewidth}{\vspace{4pt}
      {\fontsize{20}{26}\selectfont\bfseries\color{accent!85!black} Quarantine \& Isolation}\\[2pt]
      {\fontsize{18}{24}\selectfont Evidence-based duration guidelines, updated as new variants emerged.}
    \vspace{4pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{accent!22}{\parbox{0.92\linewidth}{\vspace{4pt}
      {\fontsize{20}{26}\selectfont\bfseries\color{accent!85!black} Vaccination Campaign}\\[2pt]
      {\fontsize{18}{24}\selectfont COVAX delivered \textbf{$\sim$1.9 billion doses} to \textbf{146 countries} by mid-2023, prioritizing health workers and vulnerable populations.}
    \vspace{4pt}}}\\[6pt]
    \colorbox{accent!15}{\parbox{0.92\linewidth}{\vspace{4pt}
      {\fontsize{20}{26}\selectfont\bfseries\color{accent!85!black} Risk Communication}\\[2pt]
      {\fontsize{18}{24}\selectfont Multilingual campaigns combating misinformation across social media and traditional channels.}
    \vspace{4pt}}}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% PHASE 5 — Left column, rows 18-20
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase5, column=1, between=row18 and row20}{
  {\phasenum{5}\hspace{6pt}{\fontsize{24}{30}\selectfont\bfseries\color{primary} Recovery \& Health System Resilience}}\\[6pt]
  \fontsize{20}{28}\selectfont
  \begin{itemize}
    \item Restore routine health services disrupted during the pandemic
    \item Strengthen preparedness via updated national action plans
    \item Address long COVID and mental health impacts
    \item Conduct after-action reviews to capture lessons learned
  \end{itemize}
}

% ══════════════════════════════════════════════════
% KEY TAKEAWAY — Right column, rows 18-20
% ══════════════════════════════════════════════════
\posterbox[highlightcard, title={Key Takeaway}
]{name=takeaway, column=2, between=row18 and row20}{
  \fontsize{20}{28}\selectfont\color{textdark}
  This five-phase process---from surveillance through recovery---represents a \textbf{coordinated global health architecture} designed to save lives and build resilience against future pandemics.\\[6pt]
  \colorbox{white!90!primary}{\parbox{0.94\linewidth}{\vspace{3pt}\centering
    {\fontsize{18}{24}\selectfont\color{primary}\textbf{194 nations} working together through an unprecedented, structured response.}
  \vspace{3pt}}}
}

