\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{arrows.meta}
\pagestyle{empty}

% ── WHO Color Theme ──
\definecolor{primary}{HTML}{005EB8}
\definecolor{primarydark}{HTML}{003D7A}
\definecolor{secondary}{HTML}{0093D0}
\definecolor{accent}{HTML}{D4850B}
\definecolor{accentlight}{HTML}{F5A623}
\definecolor{bgposter}{HTML}{ECF0F6}
\definecolor{cardbg}{HTML}{FFFFFF}
\definecolor{cardtitlebg}{HTML}{E1EBF5}
\definecolor{phase4titlebg}{HTML}{FDE8C8}
\definecolor{phase4bg}{HTML}{FFF7ED}
\definecolor{textdark}{HTML}{1A2332}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{E3EFF9}
\definecolor{statamber}{HTML}{FEF0D6}
\definecolor{hopefulgreen}{HTML}{1B7340}
\definecolor{connectorcolor}{HTML}{B0C4DE}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{secondary}\raisebox{1pt}{$\bullet$}}}
\setlist[enumerate]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Phase badge command ──
\newcommand{\phasebadge}[2]{%
  \tikz[baseline=(n.base)]{%
    \node[rounded corners=3pt, fill=#1, text=white, inner xsep=8pt, inner ysep=4pt,
          font=\fontsize{22}{26}\selectfont\bfseries] (n) {PHASE~#2};%
  }%
}

% ── Down arrow connector ──
\newcommand{\downarrowconnector}{%
  \centering\tikz{\draw[-{Triangle[length=5mm,width=4mm]}, line width=2.5pt, primary!60] (0,0) -- (0,-8mm);}%
}
\newcommand{\downarrowconnectoraccent}{%
  \centering\tikz{\draw[-{Triangle[length=6mm,width=5mm]}, line width=3pt, accent] (0,0) -- (0,-8mm);}%
}

% ── Card styles ──
\tcbset{
  phasecard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{primary},
    left=12pt, right=10pt, top=6pt, bottom=6pt,
    valign=top, drop shadow={opacity=0.14},
  },
  phase4card/.style={
    enhanced, arc=3pt, boxrule=1.5pt, colframe=accent,
    colback=phase4bg,
    borderline west={5pt}{0pt}{accent},
    left=12pt, right=10pt, top=6pt, bottom=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
  infocard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{secondary},
    left=12pt, right=10pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{24}{30}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!30},
    valign=top, drop shadow={opacity=0.14},
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=primary!14!white,
    borderline west={5pt}{0pt}{primary},
    left=12pt, right=10pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{24}{30}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=6, rows=40, spacing=0mm},
]

% ══════════════════════════════════════════════════
% TITLE BAR — rows 1-5
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primarydark, colframe=primarydark, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=6, between=top and row5}{
  {\fontsize{56}{66}\selectfont\bfseries COVID-19 Emergency Response}\\[6pt]
  {\fontsize{36}{44}\selectfont\color{white!90} From Detection to Recovery}\\[10pt]
  {\fontsize{20}{26}\selectfont\color{white!70} A structured, five-phase process guided by the World Health Organization across all 6 WHO regions}
}

