  valign=center,
  borderline south={2.5pt}{0pt}{primary!25},
]{name=stats, column=1, span=6, between=row5 and row9}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.86\linewidth}{%
