263	      {\fontsize{20}{26}\selectfont Prioritizing health workers and vulnerable populations.}
264	    \vspace{6pt}}}\\[6pt]
265	    \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{5pt}
266	      {\fontsize{22}{28}\selectfont\bfseries\color{accent} Risk Communication}\\[3pt]
267	      {\fontsize{20}{26}\selectfont Multilingual campaigns combating misinformation across social media and traditional channels.}
268	    \vspace{5pt}}}
