\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{arrows.meta}
\pagestyle{empty}

% ── WHO Color Theme ──
\definecolor{primary}{HTML}{005EB8}
\definecolor{primarydark}{HTML}{003D7A}
\definecolor{secondary}{HTML}{0093D0}
\definecolor{accent}{HTML}{D4850B}
\definecolor{accentlight}{HTML}{F5A623}
\definecolor{bgposter}{HTML}{ECF0F6}
\definecolor{cardbg}{HTML}{FFFFFF}
\definecolor{cardtitlebg}{HTML}{E1EBF5}
\definecolor{phase4titlebg}{HTML}{FDE8C8}
\definecolor{phase4bg}{HTML}{FFF7ED}
\definecolor{textdark}{HTML}{1A2332}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{E3EFF9}
\definecolor{statamber}{HTML}{FEF0D6}
\definecolor{hopefulgreen}{HTML}{1B7340}
\definecolor{connectorcolor}{HTML}{B0C4DE}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{secondary}\raisebox{1pt}{$\bullet$}}}
\setlist[enumerate]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Phase badge command ──
\newcommand{\phasebadge}[2]{%
  \tikz[baseline=(n.base)]{%
    \node[rounded corners=3pt, fill=#1, text=white, inner xsep=8pt, inner ysep=4pt,
          font=\fontsize{22}{26}\selectfont\bfseries] (n) {PHASE~#2};%
  }%
}

% ── Down arrow connector ──
\newcommand{\downarrowconnector}{%
  \centering\tikz{\draw[-{Triangle[length=5mm,width=4mm]}, line width=2.5pt, primary!60] (0,0) -- (0,-8mm);}%
}
\newcommand{\downarrowconnectoraccent}{%
  \centering\tikz{\draw[-{Triangle[length=6mm,width=5mm]}, line width=3pt, accent] (0,0) -- (0,-8mm);}%
}

% ── Card styles ──
\tcbset{
  phasecard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{primary},
    left=12pt, right=10pt, top=6pt, bottom=6pt,
    valign=top, drop shadow={opacity=0.14},
  },
  phase4card/.style={
    enhanced, arc=3pt, boxrule=1.5pt, colframe=accent,
    colback=phase4bg,
    borderline west={5pt}{0pt}{accent},
    left=12pt, right=10pt, top=6pt, bottom=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
  infocard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{secondary},
    left=12pt, right=10pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{24}{30}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={primary!30},
    valign=top, drop shadow={opacity=0.14},
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=primary!14!white,
    borderline west={5pt}{0pt}{primary},
    left=12pt, right=10pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{24}{30}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=6, rows=40, spacing=0mm},
]

% ══════════════════════════════════════════════════
% TITLE BAR — rows 1-5
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primarydark, colframe=primarydark, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=6, between=top and row5}{
  {\fontsize{56}{66}\selectfont\bfseries COVID-19 Emergency Response}\\[6pt]
  {\fontsize{36}{44}\selectfont\color{white!90} From Detection to Recovery}\\[10pt]
  {\fontsize{20}{26}\selectfont\color{white!70} A structured, five-phase process guided by the World Health Organization across all 6 WHO regions}
}

% ══════════════════════════════════════════════════
% STAT BANNER — rows 5-9
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2.5pt}{0pt}{primary!25},
]{name=stats, column=1, span=6, between=row5 and row9}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{56}{66}\selectfont\bfseries\color{primary} 194}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} WHO Member States\\Coordinated}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.36\linewidth}\centering
    \fcolorbox{accent!70}{statamber}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{56}{66}\selectfont\bfseries\color{accent} \raisebox{3pt}{\fontsize{34}{40}\selectfont$\sim$}1.9B}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} COVAX Vaccine Doses\\Delivered by Mid-2023}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{56}{66}\selectfont\bfseries\color{primary} 200+}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} Technical Guidance\\Documents Issued}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% PHASE 1 — rows 9-15, left half (columns 1-3)
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase1, column=1, span=3, between=row9 and row15}{
  \phasebadge{primary}{1}~~{\fontsize{26}{32}\selectfont\bfseries\color{primary} Surveillance \& Early Detection}\\[8pt]
  \fontsize{22}{30}\selectfont
  \begin{itemize}
    \item National labs report unusual respiratory clusters to WHO via the \textbf{IHR framework}
    \item Disease Outbreak News bulletins and Weekly Epidemiological Records published globally
    \item Rapid identification of novel pathogens through established surveillance channels
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!15}{\parbox{0.94\linewidth}{\vspace{4pt}\centering
    {\fontsize{20}{26}\selectfont\color{primary} First Disease Outbreak News: \textbf{5 January 2020}}
  \vspace{4pt}}}
}

% ══════════════════════════════════════════════════
% PHASE 2 — rows 9-15, right half (columns 4-6)
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase2, column=4, span=3, between=row9 and row15}{
  \phasebadge{primary}{2}~~{\fontsize{26}{32}\selectfont\bfseries\color{primary} Risk Assessment \& Alert}\\[8pt]
  \fontsize{22}{30}\selectfont
  \begin{itemize}
    \item WHO evaluates \textbf{likelihood of spread}, severity, and health system capacity
    \item Situation reports issued regularly to all Member States
    \item Independent Oversight \& Advisory Committee reviews alert mechanisms
  \end{itemize}
  \vspace{4pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{\vspace{4pt}\centering
    {\fontsize{22}{28}\selectfont\color{accent}\textbf{PHEIC declared 30 January 2020}}
  \vspace{4pt}}}
}

% ══════════════════════════════════════════════════
% CONNECTOR ARROW 1 → 3
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=center,
]{name=arrow1, column=1, span=6, between=row15 and row16}{
  \downarrowconnector
}

% ══════════════════════════════════════════════════
% PHASE 3 — rows 16-23, full width
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase3, column=1, span=6, between=row16 and row23}{
  \phasebadge{primary}{3}~~{\fontsize{26}{32}\selectfont\bfseries\color{primary} Response Operations \& Clinical Management}\\[8pt]
  \fontsize{22}{30}\selectfont
  WHO mobilizes technical teams through the \textbf{Health Emergencies Programme}, working with UNICEF, World Bank, and M\'{e}decins Sans Fronti\`{e}res.\\[8pt]
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{4pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Infection Prevention \& Control}\\[2pt]
      {\fontsize{20}{26}\selectfont PPE guidance, hand hygiene, facility decontamination}
    \vspace{4pt}}}\\[5pt]
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{4pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Clinical Management}\\[2pt]
      {\fontsize{20}{26}\selectfont Treatment protocols, oxygen therapy, ICU guidelines}
    \vspace{4pt}}}\\[5pt]
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{4pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Health Workforce}\\[2pt]
      {\fontsize{20}{26}\selectfont Training, surge staffing, mental health support}
    \vspace{4pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{4pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Supply Chain \& Logistics}\\[2pt]
      {\fontsize{20}{26}\selectfont Essential medicines, diagnostics, equipment procurement}
    \vspace{4pt}}}\\[5pt]
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{4pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Research \& Innovation}\\[2pt]
      {\fontsize{20}{26}\selectfont Solidarity Trial, vaccine R\&D coordination}
    \vspace{4pt}}}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% CONNECTOR ARROW 3 → 4 (larger, accented)
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=center,
]{name=arrow2, column=1, span=6, between=row23 and row24}{
  \downarrowconnectoraccent
}

% ══════════════════════════════════════════════════
% PHASE 4 — rows 24-34, full width (HIGHLIGHTED — largest section)
% ══════════════════════════════════════════════════
\posterbox[phase4card
]{name=phase4, column=1, span=6, between=row24 and row34}{
  \phasebadge{accent}{4}~~{\fontsize{28}{34}\selectfont\bfseries\color{accent} Public Health \& Social Measures}\\[8pt]
  \fontsize{22}{30}\selectfont
  Community-level interventions critical to slowing transmission and protecting populations worldwide.\\[8pt]
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{accent} Testing \& Contact Tracing}\\[3pt]
      {\fontsize{20}{26}\selectfont Scaled PCR and rapid antigen testing; digital and manual contact tracing systems deployed globally.}
    \vspace{5pt}}}\\[6pt]
    \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{accent} Quarantine \& Isolation}\\[3pt]
      {\fontsize{20}{26}\selectfont Evidence-based duration guidelines, updated as new variants emerged across all 6 WHO regions.}
    \vspace{5pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \fcolorbox{accent!60}{accent!25}{\parbox{0.90\linewidth}{\vspace{6pt}
      {\fontsize{24}{30}\selectfont\bfseries\color{accent} Vaccination Campaign}\\[4pt]
      {\fontsize{22}{28}\selectfont COVAX facility delivered \textbf{$\sim$1.9 billion doses} to \textbf{146 countries} by mid-2023.}\\[3pt]
      {\fontsize{20}{26}\selectfont Prioritizing health workers and vulnerable populations.}
    \vspace{6pt}}}\\[6pt]
    \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{accent} Risk Communication}\\[3pt]
      {\fontsize{20}{26}\selectfont Multilingual campaigns combating misinformation across social media and traditional channels.}
    \vspace{5pt}}}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% CONNECTOR ARROW 4 → 5
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=center,
]{name=arrow3, column=1, span=6, between=row34 and row35}{
  \downarrowconnector
}

% ══════════════════════════════════════════════════
% PHASE 5 — rows 35-40, left half
% ══════════════════════════════════════════════════
\posterbox[phasecard
]{name=phase5, column=1, span=3, between=row35 and row40}{
  \phasebadge{hopefulgreen}{5}~~{\fontsize{26}{32}\selectfont\bfseries\color{hopefulgreen} Recovery \& Resilience}\\[8pt]
  \fontsize{22}{30}\selectfont
  \begin{itemize}
    \item Restore routine health services disrupted during the pandemic
    \item Strengthen preparedness via updated national action plans
    \item Address long COVID and mental health impacts
    \item After-action reviews to capture lessons learned
  \end{itemize}
}

% ══════════════════════════════════════════════════
% KEY TAKEAWAY — rows 35-40, right half
% ══════════════════════════════════════════════════
\posterbox[highlightcard, title={Key Takeaway}
]{name=takeaway, column=4, span=3, between=row35 and row40}{
  \fontsize{22}{30}\selectfont\color{textdark}
  This five-phase process---from surveillance through recovery---represents a \textbf{coordinated global health architecture} designed to save lives and build resilience.\\[6pt]
  \colorbox{white!85!primary}{\parbox{0.94\linewidth}{\vspace{4pt}\centering
    {\fontsize{20}{26}\selectfont\color{primary}\textbf{194 nations} working together through an unprecedented, systematic response framework.}
  \vspace{4pt}}}
}

\end{tcbposter}
\end{document}

