\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{arrows.meta}
\pagestyle{empty}

% ── WHO Color Theme ──
\definecolor{primary}{HTML}{005EB8}
\definecolor{primarydark}{HTML}{003D7A}
\definecolor{secondary}{HTML}{0093D0}
\definecolor{accent}{HTML}{D4850B}
\definecolor{accentlight}{HTML}{F5A623}
\definecolor{bgposter}{HTML}{E8EDF4}
\definecolor{cardbg}{HTML}{FFFFFF}
\definecolor{cardtitlebg}{HTML}{E1EBF5}
\definecolor{phase4bg}{HTML}{FFF7ED}
\definecolor{textdark}{HTML}{1A2332}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{E3EFF9}
\definecolor{statamber}{HTML}{FEF0D6}
\definecolor{hopefulgreen}{HTML}{1B7340}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=5pt, parsep=1pt, topsep=3pt,
  label={\color{secondary}\raisebox{1.5pt}{$\bullet$}}}

% ── Phase badge command ──
\newcommand{\phasebadge}[2]{%
  \tikz[baseline=(n.base)]{%
    \node[rounded corners=4pt, fill=#1, text=white, inner xsep=10pt, inner ysep=5pt,
          font=\fontsize{20}{24}\selectfont\bfseries] (n) {PHASE~#2};%
  }%
}

% ── Down arrow connector ──
\newcommand{\downarrowblock}{%
  \centering\tikz{%
    \draw[-{Triangle[length=6mm,width=5mm]}, line width=3pt, primary!50] (0,0) -- (0,-10mm);%
  }%
}
\newcommand{\downarrowblockaccent}{%
  \centering\tikz{%
    \draw[-{Triangle[length=7mm,width=6mm]}, line width=3.5pt, accent!80] (0,0) -- (0,-10mm);%
  }%
}

% ── Card styles ──
\tcbset{
  phasecard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{primary},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    valign=top, drop shadow={opacity=0.14},
  },
  phase4card/.style={
    enhanced, arc=3pt, boxrule=2pt, colframe=accent,
    colback=phase4bg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    valign=top, drop shadow={opacity=0.24},
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=primary!14!white,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{24}{30}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

