\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{arrows.meta}
\pagestyle{empty}

% ── WHO Color Theme ──
\definecolor{primary}{HTML}{005EB8}
\definecolor{primarydark}{HTML}{003D7A}
\definecolor{secondary}{HTML}{0093D0}
\definecolor{accent}{HTML}{D4850B}
\definecolor{bgposter}{HTML}{E8EDF4}
\definecolor{cardbg}{HTML}{FFFFFF}
\definecolor{phase4bg}{HTML}{FFF7ED}
\definecolor{textdark}{HTML}{1A2332}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{E3EFF9}
\definecolor{statamber}{HTML}{FEF0D6}
\definecolor{hopefulgreen}{HTML}{1B7340}

\pagecolor{bgposter}
\color{textdark}

\setlist[itemize]{leftmargin=18pt, itemsep=5pt, parsep=1pt, topsep=3pt,
  label={\color{secondary}\raisebox{1.5pt}{$\bullet$}}}

\newcommand{\phasebadge}[2]{%
  \tikz[baseline=(n.base)]{%
    \node[rounded corners=4pt, fill=#1, text=white, inner xsep=10pt, inner ysep=5pt,
          font=\fontsize{20}{24}\selectfont\bfseries] (n) {PHASE~#2};%
  }%
}

\newcommand{\downarrowblock}{%
  \centering\tikz{%
    \draw[-{Triangle[length=6mm,width=5mm]}, line width=3pt, primary!50] (0,0) -- (0,-12mm);%
  }%
}
\newcommand{\downarrowblockaccent}{%
  \centering\tikz{%
    \draw[-{Triangle[length=7mm,width=6mm]}, line width=3.5pt, accent!80] (0,0) -- (0,-12mm);%
  }%
}

\tcbset{
  phasecard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{primary},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    valign=top, drop shadow={opacity=0.14},
  },
  phase4card/.style={
    enhanced, arc=3pt, boxrule=2pt, colframe=accent,
    colback=phase4bg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    valign=top, drop shadow={opacity=0.24},
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=primary!14!white,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{24}{30}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=40, spacing=1mm},
]

% ── TITLE BAR ── rows 1-5
\posterbox[
  enhanced, colback=primarydark, colframe=primarydark, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=14pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row5}{
  {\fontsize{54}{64}\selectfont\bfseries COVID-19 Emergency Response}\\[6pt]
  {\fontsize{34}{42}\selectfont\color{white!90} From Detection to Recovery}\\[10pt]
  {\fontsize{18}{24}\selectfont\color{white!70} A structured, five-phase process guided by the World Health Organization across all 6 WHO regions}
}

% ── STAT BANNER ── rows 5-9
\posterbox[
  enhanced, colback=white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2.5pt}{0pt}{primary!25},
]{name=stats, column=1, span=2, between=row5 and row9}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.84\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{primary} 194}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textdark} WHO Member States\\Coordinated}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.35\linewidth}\centering
    \fcolorbox{accent!70}{statamber}{\parbox{0.84\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{accent} \raisebox{2pt}{\fontsize{32}{38}\selectfont$\sim$}1.9B}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textdark} COVAX Vaccine Doses\\Delivered by Mid-2023}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.84\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{primary} 200+}\\[3pt]
      {\fontsize{18}{24}\selectfont\color{textdark} Technical Guidance\\Documents Issued}\vspace{6pt}%
    }}
  \end{minipage}
}

% ── PHASE 1 ── rows 10-16, left
\posterbox[phasecard
]{name=phase1, column=1, between=row10 and row16}{
  \phasebadge{primary}{1}~~{\fontsize{24}{30}\selectfont\bfseries\color{primary} Surveillance \& Early Detection}\\[8pt]
  \fontsize{22}{30}\selectfont
  \begin{itemize}
    \item National labs report respiratory clusters to WHO via \textbf{IHR framework}
    \item Disease Outbreak News bulletins keep the global community informed
    \item Rapid identification of novel pathogens through surveillance channels
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!15}{\parbox{0.94\linewidth}{\vspace{4pt}\centering
    {\fontsize{20}{26}\selectfont\color{primary} First Disease Outbreak News: \textbf{5 January 2020}}
  \vspace{4pt}}}
}

% ── PHASE 2 ── rows 10-16, right
\posterbox[phasecard
]{name=phase2, column=2, between=row10 and row16}{
  \phasebadge{primary}{2}~~{\fontsize{24}{30}\selectfont\bfseries\color{primary} Risk Assessment \& Alert}\\[8pt]
  \fontsize{22}{30}\selectfont
  \begin{itemize}
    \item WHO evaluates \textbf{likelihood of spread}, severity, and health system capacity
    \item Situation reports issued regularly to all Member States
    \item Independent Oversight Committee reviews alert adequacy
  \end{itemize}
  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{\vspace{4pt}\centering
    {\fontsize{20}{26}\selectfont\color{accent}\textbf{PHEIC declared 30 January 2020}}
  \vspace{4pt}}}
}

% ── ARROW 1→3 ──
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  halign=center, valign=center,
]{name=arrow1, column=1, span=2, between=row16 and row17}{
  \downarrowblock
}

% ── PHASE 3 ── rows 17-23, full width
\posterbox[phasecard
]{name=phase3, column=1, span=2, between=row17 and row23}{
  \phasebadge{primary}{3}~~{\fontsize{24}{30}\selectfont\bfseries\color{primary} Response Operations \& Clinical Management}\\[8pt]
  \fontsize{22}{30}\selectfont
  WHO mobilizes teams through the \textbf{Health Emergencies Programme}, with UNICEF, World Bank, and MSF.\\[8pt]
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Infection Prevention \& Control}\\[2pt]
      {\fontsize{20}{26}\selectfont PPE guidance, hand hygiene, facility decontamination}
    \vspace{5pt}}}\\[6pt]
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Clinical Management}\\[2pt]
      {\fontsize{20}{26}\selectfont Treatment protocols, oxygen therapy, ICU guidelines}
    \vspace{5pt}}}\\[6pt]
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Health Workforce}\\[2pt]
      {\fontsize{20}{26}\selectfont Training, surge staffing, mental health support}
    \vspace{5pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Supply Chain \& Logistics}\\[2pt]
      {\fontsize{20}{26}\selectfont Essential medicines, diagnostics, equipment procurement}
    \vspace{5pt}}}\\[6pt]
    \colorbox{primary!12}{\parbox{0.94\linewidth}{\vspace{5pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{primary} Research \& Innovation}\\[2pt]
      {\fontsize{20}{26}\selectfont Solidarity Trial, vaccine R\&D coordination}
    \vspace{5pt}}}
  \end{minipage}
}

% ── ARROW 3→4 (accented) ──
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  halign=center, valign=center,
]{name=arrow2, column=1, span=2, between=row23 and row24}{
  \downarrowblockaccent
}

% ── PHASE 4 ── rows 24-32, full width (HIGHLIGHTED)
\posterbox[phase4card
]{name=phase4, column=1, span=2, between=row24 and row32}{
  \phasebadge{accent}{4}~~{\fontsize{26}{32}\selectfont\bfseries\color{accent} Public Health \& Social Measures}\\[8pt]
  \fontsize{22}{30}\selectfont
  Community-level interventions critical to slowing transmission and protecting populations worldwide.\\[10pt]
  \begin{minipage}[t]{0.48\linewidth}
    \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{6pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{accent} Testing \& Contact Tracing}\\[3pt]
      {\fontsize{20}{26}\selectfont Scaled PCR and rapid antigen testing; digital and manual contact tracing systems deployed globally.}
    \vspace{6pt}}}\\[8pt]
    \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{6pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{accent} Quarantine \& Isolation}\\[3pt]
      {\fontsize{20}{26}\selectfont Evidence-based duration guidelines, updated as new variants emerged across all 6 WHO regions.}
    \vspace{6pt}}}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \fcolorbox{accent!60}{accent!22}{\parbox{0.90\linewidth}{\vspace{7pt}
      {\fontsize{24}{30}\selectfont\bfseries\color{accent} Vaccination Campaign}\\[4pt]
      {\fontsize{22}{28}\selectfont COVAX delivered \textbf{$\sim$1.9 billion doses} to \textbf{146 countries} by mid-2023.}\\[4pt]
      {\fontsize{20}{26}\selectfont Prioritizing health workers and vulnerable populations.}
    \vspace{7pt}}}\\[8pt]
    \colorbox{accent!18}{\parbox{0.94\linewidth}{\vspace{6pt}
      {\fontsize{22}{28}\selectfont\bfseries\color{accent} Risk Communication}\\[3pt]
      {\fontsize{20}{26}\selectfont Multilingual campaigns combating misinformation across social media and traditional channels.}
    \vspace{6pt}}}
  \end{minipage}
}

% ── ARROW 4→5 ──
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  halign=center, valign=center,
]{name=arrow3, column=1, span=2, between=row32 and row33}{
  \downarrowblock
}

% ── PHASE 5 ── rows 33-40, left
\posterbox[phasecard
]{name=phase5, column=1, between=row33 and row40}{
