  \phasebadge{hopefulgreen}{5}~~{\fontsize{24}{30}\selectfont\bfseries\color{hopefulgreen} Recovery \& Resilience}\\[8pt]
  \fontsize{22}{30}\selectfont
  \begin{itemize}
